cat > src/params.rs <<'EOF'
//! Typed access to the members of a command object (SPEC section 1).
//!
//! A member whose value is `null` is treated as absent everywhere.

use serde_json::{Map, Value};

use crate::error::{ApiError, ErrorCode, Result};

#[derive(Clone, Copy)]
pub struct Params<'a>(&'a Map<String, Value>);

impl<'a> Params<'a> {
    pub fn new(members: &'a Map<String, Value>) -> Self {
        Self(members)
    }

    fn get(&self, name: &str) -> Option<&'a Value> {
        self.0.get(name).filter(|v| !v.is_null())
    }

    pub fn has(&self, name: &str) -> bool {
        self.get(name).is_some()
    }

    /// Fails with `MissingParameter` for the first of `names` that is absent.
    pub fn require(&self, names: &[&str]) -> Result<()> {
        match names.iter().find(|n| !self.has(n)) {
            Some(name) => Err(missing(name)),
            None => Ok(()),
        }
    }

    pub fn string(&self, name: &str) -> Result<Option<&'a str>> {
        self.get(name)
            .map(|v| {
                v.as_str()
                    .ok_or_else(|| invalid(name, "must be a string"))
            })
            .transpose()
    }

    pub fn required_string(&self, name: &str) -> Result<&'a str> {
        self.string(name)?.ok_or_else(|| missing(name))
    }

    pub fn string_where(
        &self,
        name: &str,
        rule: &str,
        accepts: impl Fn(&str) -> bool,
    ) -> Result<Option<&'a str>> {
        match self.string(name)? {
            Some(s) if !accepts(s) => Err(invalid(name, rule)),
            other => Ok(other),
        }
    }

    /// An integer written without fraction or exponent, within `min..=max`.
    pub fn int(&self, name: &str, min: u64, max: u64) -> Result<Option<u64>> {
        self.get(name)
            .map(|v| match v.as_u64() {
                Some(n) if (min..=max).contains(&n) => Ok(n),
                _ => Err(invalid(name, &format!("must be an integer from {min} to {max}"))),
            })
            .transpose()
    }

    pub fn required_int(&self, name: &str, min: u64, max: u64) -> Result<u64> {
        self.int(name, min, max)?.ok_or_else(|| missing(name))
    }

    pub fn bool(&self, name: &str) -> Result<Option<bool>> {
        self.get(name)
            .map(|v| v.as_bool().ok_or_else(|| invalid(name, "must be a boolean")))
            .transpose()
    }

    pub fn object(&self, name: &str) -> Result<Option<&'a Map<String, Value>>> {
        self.get(name)
            .map(|v| v.as_object().ok_or_else(|| invalid(name, "must be an object")))
            .transpose()
    }

    pub fn members(&self) -> &'a Map<String, Value> {
        self.0
    }
}

fn missing(name: &str) -> ApiError {
    ApiError::new(ErrorCode::MissingParameter, format!("{name} is required"))
}

fn invalid(name: &str, rule: &str) -> ApiError {
    ApiError::new(ErrorCode::InvalidParameterValue, format!("{name} {rule}"))
}
