cat > src/queue.rs <<'EOF'
//! Queue state: attributes, messages and the bookkeeping that keeps
//! retention and deduplication cheap (SPEC section 4).

use std::collections::{BTreeMap, BTreeSet, HashMap};
use std::sync::Arc;

use serde_json::Map;

use crate::error::{ApiError, ErrorCode, Result};
use crate::params::Params;

pub const MAX_MESSAGES_PER_QUEUE: usize = 100_000;
pub const DEDUPLICATION_WINDOW: u64 = 300;

const FIFO_SUFFIX: &str = ".fifo";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DeadLetter {
    pub queue: String,
    pub max_receive_count: u64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Config {
    pub visibility_timeout: u64,
    pub delay_seconds: u64,
    pub retention_seconds: u64,
    pub fifo: bool,
    pub content_based_deduplication: bool,
    pub dead_letter: Option<DeadLetter>,
}

/// The attributes named in one request; absent ones are `None`.
#[derive(Debug, Default)]
pub struct AttributeUpdate {
    pub visibility_timeout: Option<u64>,
    pub delay_seconds: Option<u64>,
    pub retention_seconds: Option<u64>,
    pub fifo: Option<bool>,
    pub content_based_deduplication: Option<bool>,
    pub dead_letter_queue: Option<String>,
    pub max_receive_count: Option<u64>,
}

const ATTRIBUTE_NAMES: [&str; 7] = [
    "VisibilityTimeout",
    "DelaySeconds",
    "RetentionSeconds",
    "Fifo",
    "ContentBasedDeduplication",
    "DeadLetterQueue",
    "MaxReceiveCount",
];

impl AttributeUpdate {
    pub fn parse(members: &Map<String, serde_json::Value>) -> Result<Self> {
        let p = Params::new(members);
        // Unknown names count only if their value is not null.
        if let Some((name, _)) = members
            .iter()
            .find(|(k, v)| !v.is_null() && !ATTRIBUTE_NAMES.contains(&k.as_str()))
        {
            return Err(ApiError::new(
                ErrorCode::InvalidParameterValue,
                format!("unknown attribute {name}"),
            ));
        }
        Ok(Self {
            visibility_timeout: p.int("VisibilityTimeout", 0, 43_200)?,
            delay_seconds: p.int("DelaySeconds", 0, 900)?,
            retention_seconds: p.int("RetentionSeconds", 60, 1_209_600)?,
            fifo: p.bool("Fifo")?,
            content_based_deduplication: p.bool("ContentBasedDeduplication")?,
            dead_letter_queue: p.string("DeadLetterQueue")?.map(str::to_owned),
            max_receive_count: p.int("MaxReceiveCount", 1, 1000)?,
        })
    }

    /// Exactly one of the two dead-letter attributes is present.
    pub fn has_half_dead_letter(&self) -> bool {
        self.dead_letter_queue.is_some() != self.max_receive_count.is_some()
    }

    pub fn dead_letter(&self) -> Option<DeadLetter> {
        Some(DeadLetter {
            queue: self.dead_letter_queue.clone()?,
            max_receive_count: self.max_receive_count?,
        })
    }
}

impl Config {
    pub fn from_update(u: &AttributeUpdate) -> Self {
        Self {
            visibility_timeout: u.visibility_timeout.unwrap_or(30),
            delay_seconds: u.delay_seconds.unwrap_or(0),
            retention_seconds: u.retention_seconds.unwrap_or(345_600),
            fifo: u.fifo.unwrap_or(false),
            content_based_deduplication: u.content_based_deduplication.unwrap_or(false),
            dead_letter: u.dead_letter(),
        }
    }

    pub fn apply(&mut self, u: AttributeUpdate) {
        let dead_letter = u.dead_letter();
        self.visibility_timeout = u.visibility_timeout.unwrap_or(self.visibility_timeout);
        self.delay_seconds = u.delay_seconds.unwrap_or(self.delay_seconds);
        self.retention_seconds = u.retention_seconds.unwrap_or(self.retention_seconds);
        self.content_based_deduplication = u
            .content_based_deduplication
            .unwrap_or(self.content_based_deduplication);
        if dead_letter.is_some() {
            self.dead_letter = dead_letter;
        }
    }
}

pub fn is_valid_queue_name(name: &str) -> bool {
    let (base, max) = match name.strip_suffix(FIFO_SUFFIX) {
        Some(base) => (base, 75),
        None => (name, 80),
    };
    (1..=max).contains(&base.len()) && base.bytes().all(is_name_byte)
}

pub fn has_fifo_suffix(name: &str) -> bool {
    name.ends_with(FIFO_SUFFIX)
}

fn is_name_byte(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'_' || b == b'-'
}

/// A `GroupId` or `DeduplicationId`.
pub fn is_valid_id(s: &str) -> bool {
    (1..=128).contains(&s.len()) && s.bytes().all(is_name_byte)
}

#[derive(Debug)]
pub struct Message {
    pub id: u64,
    pub body: String,
    pub sent_at: u64,
    pub receive_count: u64,
    pub first_received_at: Option<u64>,
    pub group: Option<Arc<str>>,
    pub sequence: Option<u64>,
    /// Delayed while `now < delayed_until`.
    pub delayed_until: u64,
    /// In flight while `now < in_flight_until`.
    pub in_flight_until: u64,
    /// The latest receipt handle issued for this message.
    pub handle: Option<u64>,
}

impl Message {
    pub fn is_delayed(&self, now: u64) -> bool {
        now < self.delayed_until
    }

    pub fn is_in_flight(&self, now: u64) -> bool {
        now < self.in_flight_until
    }

    pub fn is_visible(&self, now: u64) -> bool {
        !self.is_delayed(now) && !self.is_in_flight(now)
    }
}

#[derive(Debug, Clone, Copy)]
pub struct Accepted {
    pub at: u64,
    pub message_id: u64,
    pub sequence: Option<u64>,
}

#[derive(Debug)]
pub struct Queue {
    /// Distinguishes this queue from an earlier one of the same name.
    pub uid: u64,
    pub config: Config,
    /// Messages by arrival key, which grows with every message added.
    messages: BTreeMap<u64, Message>,
    /// `(sent_at, key)` of every message, so retention only looks at the oldest.
    by_sent_at: BTreeSet<(u64, u64)>,
    next_key: u64,
    next_sequence: u64,
    /// Deduplication id to the send that opened its current window.
    pub deduplication: HashMap<String, Accepted>,
}

impl Queue {
    pub fn new(uid: u64, config: Config) -> Self {
        Self {
            uid,
            config,
            messages: BTreeMap::new(),
            by_sent_at: BTreeSet::new(),
            next_key: 0,
            next_sequence: 1,
            deduplication: HashMap::new(),
        }
    }

    pub fn len(&self) -> usize {
        self.messages.len()
    }

    pub fn get_mut(&mut self, key: u64) -> Option<&mut Message> {
        self.messages.get_mut(&key)
    }

    pub fn messages(&self) -> impl Iterator<Item = &Message> {
        self.messages.values()
    }

    pub fn messages_mut(&mut self) -> impl Iterator<Item = (u64, &mut Message)> {
        self.messages.iter_mut().map(|(k, m)| (*k, m))
    }

    /// Adds `message` at the end; returns its sequence number on a FIFO queue.
    pub fn push(&mut self, mut message: Message) -> Option<u64> {
        message.sequence = self.config.fifo.then(|| {
            let n = self.next_sequence;
            self.next_sequence += 1;
            n
        });
        let sequence = message.sequence;
        self.by_sent_at.insert((message.sent_at, self.next_key));
        self.messages.insert(self.next_key, message);
        self.next_key += 1;
        sequence
    }

    pub fn remove(&mut self, key: u64) -> Option<Message> {
        let message = self.messages.remove(&key)?;
        self.by_sent_at.remove(&(message.sent_at, key));
        Some(message)
    }

    pub fn clear(&mut self) {
        self.messages.clear();
        self.by_sent_at.clear();
    }

    /// Drops every message whose retention has run out at `now`.
    pub fn expire(&mut self, now: u64) {
        let retention = self.config.retention_seconds;
        while let Some(&(sent_at, key)) = self.by_sent_at.first() {
            if sent_at + retention > now {
                break;
            }
            self.by_sent_at.pop_first();
            self.messages.remove(&key);
        }
    }
}
EOF
