    pub receive_count: u64,
    pub first_received_at: Option<u64>,
    pub group: Option<Arc<str>>,
    pub sequence: Option<u64>,
    /// Delayed while `now < delayed_until`.
    pub delayed_until: u64,
    /// In flight while `now < in_flight_until`.
    pub in_flight_until: u64,
    /// The latest receipt handle issued for this message.
    pub handle: Option<u64>,
}

impl Message {
    pub fn is_delayed(&self, now: u64) -> bool {
        now < self.delayed_until
    }

    pub fn is_in_flight(&self, now: u64) -> bool {
        now < self.in_flight_until
    }

    pub fn is_visible(&self, now: u64) -> bool {
        !self.is_delayed(now) && !self.is_in_flight(now)
    }
}

#[derive(Debug, Clone, Copy)]
pub struct Accepted {
    pub at: u64,
    pub message_id: u64,
    pub sequence: Option<u64>,
}

#[derive(Debug)]
pub struct Queue {
    /// Distinguishes this queue from an earlier one of the same name.
    pub uid: u64,
    pub config: Config,
    /// Messages by arrival key, which grows with every message added.
    messages: BTreeMap<u64, Message>,
    /// `(sent_at, key)` of every message, so retention only looks at the oldest.
    by_sent_at: BTreeSet<(u64, u64)>,
    next_key: u64,
    next_sequence: u64,
    /// Deduplication id to the send that opened its current window.
    pub deduplication: HashMap<String, Accepted>,
}

impl Queue {
    pub fn new(uid: u64, config: Config) -> Self {
        Self {
            uid,
            config,
            messages: BTreeMap::new(),
            by_sent_at: BTreeSet::new(),
            next_key: 0,
            next_sequence: 1,
            deduplication: HashMap::new(),
        }
    }

    pub fn len(&self) -> usize {
        self.messages.len()
    }

    pub fn get_mut(&mut self, key: u64) -> Option<&mut Message> {
        self.messages.get_mut(&key)
    }

    pub fn messages(&self) -> impl Iterator<Item = &Message> {
        self.messages.values()
    }

    pub fn messages_mut(&mut self) -> impl Iterator<Item = (u64, &mut Message)> {
        self.messages.iter_mut().map(|(k, m)| (*k, m))
    }

    /// Adds `message` at the end; returns its sequence number on a FIFO queue.
    pub fn push(&mut self, mut message: Message) -> Option<u64> {
        message.sequence = self.config.fifo.then(|| {
            let n = self.next_sequence;
            self.next_sequence += 1;
            n
        });
        let sequence = message.sequence;
        self.by_sent_at.insert((message.sent_at, self.next_key));
        self.messages.insert(self.next_key, message);
        self.next_key += 1;
        sequence
    }

    pub fn remove(&mut self, key: u64) -> Option<Message> {
        let message = self.messages.remove(&key)?;
        self.by_sent_at.remove(&(message.sent_at, key));
        Some(message)
    }

    pub fn clear(&mut self) {
        self.messages.clear();
        self.by_sent_at.clear();
    }

    /// Drops every message whose retention has run out at `now`.
    pub fn expire(&mut self, now: u64) {
        let retention = self.config.retention_seconds;
        while let Some(&(sent_at, key)) = self.by_sent_at.first() {
            if sent_at + retention > now {
                break;
            }
            self.by_sent_at.pop_first();
            self.messages.remove(&key);
        }
    }
}
