        }
    }

    fn queue(&mut self, name: &str) -> Result<&mut Queue> {
        lookup(&mut self.queues, name, self.now)
    }

    fn create_queue(&mut self, p: Params) -> Result<Members> {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        if !is_valid_queue_name(name) {
            return Err(err(ErrorCode::QueueNameInvalid, "queue name breaks the naming rules"));
        }
        let update = p
            .object("Attributes")?
            .map(AttributeUpdate::parse)
            .transpose()?
            .unwrap_or_default();
        let config = Config::from_update(&update);
        if has_fifo_suffix(name) != config.fifo {
            return Err(err(
                ErrorCode::QueueNameInvalid,
                "the .fifo suffix and the Fifo attribute must agree",
            ));
        }
        if config.content_based_deduplication && !config.fifo {
            return Err(invalid("ContentBasedDeduplication needs a FIFO queue"));
        }
        if update.has_half_dead_letter() {
            return Err(invalid("DeadLetterQueue and MaxReceiveCount go together"));
        }
        if let Some(existing) = self.queues.get(name) {
            return if existing.config == config {
                Ok(Members::new())
            } else {
                Err(err(ErrorCode::QueueAlreadyExists, "queue exists with different attributes"))
            };
        }
        if let Some(dl) = &config.dead_letter {
            let target = self.queues.get(&dl.queue).ok_or_else(no_such_queue)?;
            if target.config.fifo != config.fifo {
                return Err(invalid("dead-letter queue must have the same Fifo setting"));
            }
        }
        if self.queues.len() >= MAX_QUEUES {
            return Err(err(ErrorCode::LimitExceeded, "too many queues"));
        }
        self.queues_created += 1;
        self.queues
            .insert(name.to_owned(), Queue::new(self.queues_created, config));
        Ok(Members::new())
    }

    fn set_queue_attributes(&mut self, p: Params) -> Result<Members> {
        p.require(&["QueueName", "Attributes"])?;
        let name = p.required_string("QueueName")?;
        let attributes = p
            .object("Attributes")?
            .ok_or_else(|| invalid("Attributes must be an object"))?;
        let update = AttributeUpdate::parse(attributes)?;
        let queue = lookup(&mut self.queues, name, self.now)?;
        if update.fifo.is_some() {
            return Err(err(ErrorCode::UnsupportedOperation, "the type of a queue never changes"));
        }
        if update.content_based_deduplication == Some(true) && !queue.config.fifo {
            return Err(invalid("ContentBasedDeduplication needs a FIFO queue"));
        }
        if update.has_half_dead_letter() {
            return Err(invalid("DeadLetterQueue and MaxReceiveCount go together"));
        }
        let fifo = queue.config.fifo;
        if let Some(target) = &update.dead_letter_queue {
            let other = self.queues.get(target).ok_or_else(no_such_queue)?;
            if target == name || other.config.fifo != fifo {
                return Err(invalid("not a usable dead-letter queue"));
            }
        }
        self.queue(name)?.config.apply(update);
        Ok(Members::new())
    }

    fn get_queue_attributes(&mut self, p: Params) -> Result<Members> {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        let now = self.now;
        let queue = lookup(&mut self.queues, name, now)?;
        let c = &queue.config;
        let mut attributes = json!({
            "VisibilityTimeout": c.visibility_timeout,
            "DelaySeconds": c.delay_seconds,
            "RetentionSeconds": c.retention_seconds,
            "Fifo": c.fifo,
            "ContentBasedDeduplication": c.content_based_deduplication,
        });
        if let Some(dl) = &c.dead_letter {
            attributes["DeadLetterQueue"] = json!(dl.queue);
            attributes["MaxReceiveCount"] = json!(dl.max_receive_count);
        }
        let (mut visible, mut in_flight, mut delayed) = (0, 0, 0);
        for m in queue.messages() {
            if m.is_delayed(now) {
                delayed += 1;
            } else if m.is_in_flight(now) {
                in_flight += 1;
            } else {
                visible += 1;
            }
        }
        Ok(result([
            ("Attributes", attributes),
            (
                "Counts",
                json!({"Visible": visible, "InFlight": in_flight, "Delayed": delayed}),
            ),
        ]))
    }

    fn list_queues(&mut self, p: Params) -> Result<Members> {
        let prefix = p.string("Prefix")?.unwrap_or("");
        let mut names: Vec<&String> = self.queues.keys().filter(|n| n.starts_with(prefix)).collect();
        names.sort_unstable();
        Ok(result([("QueueNames", json!(names))]))
    }

    fn delete_queue(&mut self, p: Params) -> Result<Members> {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        self.queue(name)?;
        self.queues.remove(name);
        for queue in self.queues.values_mut() {
            if queue.config.dead_letter.as_ref().is_some_and(|dl| dl.queue == name) {
                queue.config.dead_letter = None;
            }
        }
        Ok(Members::new())
    }

    fn purge_queue(&mut self, p: Params) -> Result<Members> {
        p.require(&["QueueName"])?;
        self.queue(p.required_string("QueueName")?)?.clear();
        Ok(Members::new())
    }

    fn tick(&mut self, p: Params) -> Result<Members> {
        p.require(&["Seconds"])?;
        self.now += p.required_int("Seconds", 0, 1_209_600)?;
        Ok(result([("Now", json!(self.now))]))
    }

    fn send_message(&mut self, p: Params) -> Result<Members> {
        p.require(&["QueueName", "Body"])?;
        let name = p.required_string("QueueName")?;
        let body = p
            .string_where("Body", "must be 1 to 1024 bytes", |s| (1..=1024).contains(&s.len()))?
            .ok_or_else(|| invalid("Body is required"))?;
        let delay = p.int("DelaySeconds", 0, 900)?;
        let group = p.string_where("GroupId", "must be 1 to 128 characters of A-Za-z0-9_-", is_valid_id)?;
        let dedup = p.string_where(
            "DeduplicationId",
            "must be 1 to 128 characters of A-Za-z0-9_-",
            is_valid_id,
        )?;

        let now = self.now;
        let queue = lookup(&mut self.queues, name, now)?;
        let unsupported = if queue.config.fifo {
            delay.is_some()
        } else {
            group.is_some() || dedup.is_some()
        };
        if unsupported {
            return Err(err(
                ErrorCode::UnsupportedOperation,
                "parameter not supported by this type of queue",
            ));
        }
        let mut dedup_id = None;
        if queue.config.fifo {
            let group = group.ok_or_else(|| missing("GroupId"))?;
            if dedup.is_none() && !queue.config.content_based_deduplication {
                return Err(missing("DeduplicationId"));
            }
            let id = dedup.unwrap_or(body);
            if let Some(original) = queue
                .deduplication
                .get(id)
                .filter(|a| now - a.at < DEDUPLICATION_WINDOW)
            {
                return Ok(send_result(original.message_id, original.sequence));
            }
            dedup_id = Some(id);
            let _ = group;
        }
        if queue.len() >= MAX_MESSAGES_PER_QUEUE {
            return Err(err(ErrorCode::LimitExceeded, "queue is full"));
        }

        self.messages_accepted += 1;
        let id = self.messages_accepted;
        let delay = delay.unwrap_or(queue.config.delay_seconds);
        let sequence = queue.push(Message {
            id,
            body: body.to_owned(),
            sent_at: now,
            receive_count: 0,
            first_received_at: None,
            group: group.map(Arc::from),
            sequence: None,
            delayed_until: now + delay,
            in_flight_until: 0,
            handle: None,
        });
        if let Some(dedup_id) = dedup_id {
            queue.deduplication.insert(
                dedup_id.to_owned(),
                Accepted { at: now, message_id: id, sequence },
            );
        }
        Ok(send_result(id, sequence))
    }

    fn receive_message(&mut self, p: Params) -> Result<Members> {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        let max = p.int("MaxMessages", 1, 10)?.unwrap_or(1) as usize;
        let requested_timeout = p.int("VisibilityTimeout", 0, MAX_VISIBILITY_TIMEOUT)?;

        let now = self.now;
        let queue = lookup(&mut self.queues, name, now)?;
        let timeout = requested_timeout.unwrap_or(queue.config.visibility_timeout);
        let dead_letter = queue.config.dead_letter.clone();
        let fifo = queue.config.fifo;
        let queue_uid = queue.uid;

        let mut delivered = Vec::new();
        let mut dead = Vec::new();
        let mut blocked_groups = std::collections::HashSet::new();
        for (key, m) in queue.messages_mut() {
            if delivered.len() == max {
                break;
            }
            let eligible = m.is_visible(now) && !m.group.as_ref().is_some_and(|g| blocked_groups.contains(g));
            // A group stays blocked by its earliest message, unless that one leaves the queue.
            let leaves = eligible
                && dead_letter.as_ref().is_some_and(|dl| m.receive_count >= dl.max_receive_count);
            if fifo && !leaves {
                if let Some(g) = &m.group {
                    blocked_groups.insert(Arc::clone(g));
                }
            }
            if !eligible {
                continue;
            }
            if leaves {
                dead.push(key);
                continue;
            }
            self.handles_issued += 1;
            m.receive_count += 1;
            m.first_received_at.get_or_insert(now);
            m.handle = Some(self.handles_issued);
            m.in_flight_until = now + timeout;
            self.handles.insert(self.handles_issued, (queue_uid, key));
            let mut out = json!({
                "MessageId": format!("m-{}", m.id),
                "ReceiptHandle": format!("r-{}", self.handles_issued),
                "Body": m.body,
                "ReceiveCount": m.receive_count,
                "SentAt": m.sent_at,
                "FirstReceivedAt": m.first_received_at,
            });
            if fifo {
                out["GroupId"] = json!(m.group.as_deref());
                out["SequenceNumber"] = json!(m.sequence);
            }
            delivered.push(out);
        }

        if let Some(dl) = dead_letter {
            let moved: Vec<Message> = dead.into_iter().filter_map(|k| queue.remove(k)).collect();
            let target = lookup(&mut self.queues, &dl.queue, now)?;
            for m in moved {
                target.push(Message {
                    receive_count: 0,
                    first_received_at: None,
                    sequence: None,
                    delayed_until: 0,
                    in_flight_until: 0,
                    handle: None,
                    ..m
                });
            }
            target.expire(now);
        }
        Ok(result([("Messages", Value::Array(delivered))]))
    }

    /// Finds the in-flight message that `handle` is the latest handle of.
    fn locate(&mut self, name: &str, handle: &str) -> Result<(&mut Queue, u64)> {
        let now = self.now;
        let issued = self.handles_issued;
        let queue = lookup(&mut self.queues, name, now)?;
        let number = parse_handle(handle, issued)
            .ok_or_else(|| err(ErrorCode::ReceiptHandleInvalid, "receipt handle was never issued"))?;
        let expired = || err(ErrorCode::ReceiptHandleExpired, "receipt handle is no longer usable");
        let &(uid, key) = self.handles.get(&number).ok_or_else(expired)?;
        let usable = uid == queue.uid
            && queue
                .get_mut(key)
                .is_some_and(|m| m.handle == Some(number) && m.is_in_flight(now));
        if usable { Ok((queue, key)) } else { Err(expired()) }
    }

    fn delete_message(&mut self, p: Params) -> Result<Members> {
        p.require(&["QueueName", "ReceiptHandle"])?;
        let (name, handle) = (p.required_string("QueueName")?, p.required_string("ReceiptHandle")?);
        let (queue, key) = self.locate(name, handle)?;
        queue.remove(key);
        Ok(Members::new())
    }

    fn change_message_visibility(&mut self, p: Params) -> Result<Members> {
        p.require(&["QueueName", "ReceiptHandle", "VisibilityTimeout"])?;
        let (name, handle) = (p.required_string("QueueName")?, p.required_string("ReceiptHandle")?);
        let timeout = p.required_int("VisibilityTimeout", 0, MAX_VISIBILITY_TIMEOUT)?;
        let now = self.now;
        let (queue, key) = self.locate(name, handle)?;
        if let Some(m) = queue.get_mut(key) {
            m.in_flight_until = now + timeout;
        }
        Ok(Members::new())
    }
}

/// Finds a queue and applies retention so callers see only live messages.
fn lookup<'a>(queues: &'a mut HashMap<String, Queue>, name: &str, now: u64) -> Result<&'a mut Queue> {
    let queue = queues.get_mut(name).ok_or_else(no_such_queue)?;
    queue.expire(now);
    Ok(queue)
}

/// `r-<n>` written exactly as miniq writes it, with `n` among the issued numbers.
fn parse_handle(handle: &str, issued: u64) -> Option<u64> {
    let n: u64 = handle.strip_prefix("r-")?.parse().ok()?;
    ((1..=issued).contains(&n) && handle == format!("r-{n}")).then_some(n)
}

fn send_result(id: u64, sequence: Option<u64>) -> Members {
    let mut out = result([("MessageId", json!(format!("m-{id}")))]);
    if let Some(s) = sequence {
        out.insert("SequenceNumber".into(), json!(s));
    }
    out
}

fn result<const N: usize>(members: [(&str, Value); N]) -> Members {
    members.into_iter().map(|(k, v)| (k.to_owned(), v)).collect()
}

fn err(code: ErrorCode, message: &str) -> ApiError {
    ApiError::new(code, message)
}

fn invalid(message: &str) -> ApiError {
    err(ErrorCode::InvalidParameterValue, message)
}

fn missing(name: &str) -> ApiError {
    ApiError::new(ErrorCode::MissingParameter, format!("{name} is required"))
}

fn no_such_queue() -> ApiError {
    err(ErrorCode::QueueDoesNotExist, "queue does not exist")
}
