mkdir -p tests && cat > tests/protocol.rs <<'EOF'
use miniq::Broker;
use serde_json::{Value, json};

fn run(broker: &mut Broker, command: Value) -> Value {
    serde_json::from_str(&broker.handle_line(command.to_string().as_bytes())).unwrap()
}

fn code(response: &Value) -> &str {
    assert_eq!(response["ok"], false, "{response}");
    response["error"]["code"].as_str().unwrap()
}

fn queue(broker: &mut Broker, name: &str, attributes: Value) {
    let r = run(broker, json!({"Command": "CreateQueue", "QueueName": name, "Attributes": attributes}));
    assert_eq!(r, json!({"ok": true}));
}

fn send(broker: &mut Broker, name: &str, body: &str) -> Value {
    run(broker, json!({"Command": "SendMessage", "QueueName": name, "Body": body}))
}

fn receive(broker: &mut Broker, name: &str) -> Value {
    run(broker, json!({"Command": "ReceiveMessage", "QueueName": name, "MaxMessages": 10}))
}

fn tick(broker: &mut Broker, seconds: u64) {
    run(broker, json!({"Command": "Tick", "Seconds": seconds}));
}

#[test]
fn malformed_lines_get_invalid_request() {
    let mut b = Broker::new();
    for line in [&b""[..], b"[]", b"{\"Command\": 3}", b"{\"Command\": \"Nope\"}", b"\xff"] {
        let r: Value = serde_json::from_str(&b.handle_line(line)).unwrap();
        assert_eq!(code(&r), "InvalidRequest");
    }
}

#[test]
fn integers_must_be_written_without_fraction_or_exponent() {
    let mut b = Broker::new();
    for seconds in ["30.0", "3e1", "\"30\""] {
        let line = format!("{{\"Command\": \"Tick\", \"Seconds\": {seconds}}}");
        let r: Value = serde_json::from_str(&b.handle_line(line.as_bytes())).unwrap();
        assert_eq!(code(&r), "InvalidParameterValue");
    }
    assert_eq!(run(&mut b, json!({"Command": "Tick", "Seconds": null}))["error"]["code"], "MissingParameter");
}

#[test]
fn create_is_idempotent_only_for_equal_attributes() {
    let mut b = Broker::new();
    queue(&mut b, "jobs", json!({}));
    queue(&mut b, "jobs", json!({"VisibilityTimeout": 30}));
    let r = run(&mut b, json!({"Command": "CreateQueue", "QueueName": "jobs", "Attributes": {"DelaySeconds": 1}}));
    assert_eq!(code(&r), "QueueAlreadyExists");
    let r = run(&mut b, json!({"Command": "CreateQueue", "QueueName": "x.fifo"}));
    assert_eq!(code(&r), "QueueNameInvalid");
}

#[test]
fn list_queues_sorts_by_byte_value() {
    let mut b = Broker::new();
    for name in ["b", "a_", "a-", "A", "a1"] {
        queue(&mut b, name, json!({}));
    }
    let r = run(&mut b, json!({"Command": "ListQueues", "Prefix": "a"}));
    assert_eq!(r["QueueNames"], json!(["a-", "a1", "a_"]));
}

#[test]
fn visibility_timeout_hides_then_redelivers_in_place() {
    let mut b = Broker::new();
    queue(&mut b, "q", json!({"VisibilityTimeout": 10}));
    assert_eq!(send(&mut b, "q", "one"), json!({"ok": true, "MessageId": "m-1"}));
    let first = receive(&mut b, "q");
    assert_eq!(first["Messages"][0]["ReceiptHandle"], "r-1");
    assert_eq!(first["Messages"][0]["FirstReceivedAt"], 0);
    assert_eq!(receive(&mut b, "q")["Messages"], json!([]));
    tick(&mut b, 10);
    let again = receive(&mut b, "q");
    assert_eq!(again["Messages"][0]["ReceiveCount"], 2);
    let stale = run(&mut b, json!({"Command": "DeleteMessage", "QueueName": "q", "ReceiptHandle": "r-1"}));
    assert_eq!(code(&stale), "ReceiptHandleExpired");
    let never = run(&mut b, json!({"Command": "DeleteMessage", "QueueName": "q", "ReceiptHandle": "r-01"}));
    assert_eq!(code(&never), "ReceiptHandleInvalid");
    let ok = run(&mut b, json!({"Command": "DeleteMessage", "QueueName": "q", "ReceiptHandle": "r-2"}));
    assert_eq!(ok, json!({"ok": true}));
}

#[test]
fn retention_removes_messages_even_after_raising_it_later() {
    let mut b = Broker::new();
    queue(&mut b, "q", json!({"RetentionSeconds": 60}));
    send(&mut b, "q", "x");
    tick(&mut b, 60);
    run(&mut b, json!({"Command": "SetQueueAttributes", "QueueName": "q", "Attributes": {"RetentionSeconds": 600}}));
    assert_eq!(receive(&mut b, "q")["Messages"], json!([]));
}

#[test]
fn fifo_delivers_one_message_per_group_and_deduplicates() {
    let mut b = Broker::new();
    queue(&mut b, "q.fifo", json!({"Fifo": true, "ContentBasedDeduplication": true}));
    let fifo_send = |b: &mut Broker, body: &str, group: &str| {
        run(b, json!({"Command": "SendMessage", "QueueName": "q.fifo", "Body": body, "GroupId": group}))
    };
    assert_eq!(fifo_send(&mut b, "a", "g1")["SequenceNumber"], 1);
    assert_eq!(fifo_send(&mut b, "a", "g2")["MessageId"], "m-1");
    fifo_send(&mut b, "b", "g1");
    fifo_send(&mut b, "c", "g2");
    let r = receive(&mut b, "q.fifo");
    let bodies: Vec<_> = r["Messages"].as_array().unwrap().iter().map(|m| m["Body"].clone()).collect();
    assert_eq!(bodies, [json!("a"), json!("c")]);
    tick(&mut b, 300);
    assert_eq!(fifo_send(&mut b, "a", "g1")["MessageId"], "m-4");
}

#[test]
fn dead_letter_moves_message_with_reset_counters() {
    let mut b = Broker::new();
    queue(&mut b, "dlq", json!({}));
    queue(&mut b, "q", json!({"VisibilityTimeout": 0, "DeadLetterQueue": "dlq", "MaxReceiveCount": 2}));
    send(&mut b, "q", "x");
    receive(&mut b, "q");
    receive(&mut b, "q");
    assert_eq!(receive(&mut b, "q")["Messages"], json!([]));
    let r = receive(&mut b, "dlq");
    assert_eq!(r["Messages"][0]["MessageId"], "m-1");
    assert_eq!(r["Messages"][0]["ReceiveCount"], 1);
}

#[test]
fn deleting_a_dead_letter_queue_clears_the_configuration() {
    let mut b = Broker::new();
    queue(&mut b, "dlq", json!({}));
    queue(&mut b, "q", json!({"DeadLetterQueue": "dlq", "MaxReceiveCount": 2}));
    run(&mut b, json!({"Command": "DeleteQueue", "QueueName": "dlq"}));
    let r = run(&mut b, json!({"Command": "GetQueueAttributes", "QueueName": "q"}));
    assert_eq!(r["Attributes"].get("DeadLetterQueue"), None);
    assert_eq!(r["Counts"], json!({"Visible": 0, "InFlight": 0, "Delayed": 0}));
}

#[test]
fn a_full_queue_is_filled_quickly_and_then_refuses_sends() {
    let mut b = Broker::new();
    queue(&mut b, "q", json!({}));
    for _ in 0..100_000 {
        assert_eq!(send(&mut b, "q", "x")["ok"], true);
    }
    assert_eq!(code(&send(&mut b, "q", "x")), "LimitExceeded");
}
